const leads = $input.all().map(i => i.json);
const today = new Date().toLocaleDateString();
const todayLeads = leads.filter(l => l.Date === today || (l['Created At'] && new Date(l['Created At']).toLocaleDateString() === today));

const valid = todayLeads.filter(l => l['Lead Temperature'] !== 'INVALID');
const invalid = todayLeads.filter(l => l['Lead Temperature'] === 'INVALID');
const hot = valid.filter(l => l['Lead Temperature'] === 'HOT');
const warm = valid.filter(l => l['Lead Temperature'] === 'WARM');
const cold = valid.filter(l => l['Lead Temperature'] === 'COLD');

const scores = valid.map(l => parseInt(l['Qualification Score'])).filter(n => !isNaN(n));
const avgScore = scores.length ? Math.round(scores.reduce((a,b)=>a+b,0)/scores.length) : 0;
const highest = valid.sort((a,b) => (parseInt(b['Qualification Score'])||0) - (parseInt(a['Qualification Score'])||0))[0];

const needs = {};
const industries = {};
valid.forEach(l => {
  if (l['AI Business Need']) needs[l['AI Business Need']] = (needs[l['AI Business Need']]||0)+1;
  if (l.Industry) industries[l.Industry] = (industries[l.Industry]||0)+1;
});
const mostCommonNeed = Object.entries(needs).sort((a,b)=>b[1]-a[1])[0]?.[0] || 'N/A';
const mostCommonIndustry = Object.entries(industries).sort((a,b)=>b[1]-a[1])[0]?.[0] || 'N/A';

return [{
  json: {
    date: today,
    generated_at: new Date().toISOString(),
    total_leads: todayLeads.length,
    valid_leads: valid.length,
    invalid_leads: invalid.length,
    hot_leads: hot.length,
    warm_leads: warm.length,
    cold_leads: cold.length,
    average_score: avgScore,
    highest_scoring_lead: highest ? { name: highest.Name, business: highest.Business, score: highest['Qualification Score'], temp: highest['Lead Temperature'] } : null,
    most_common_need: mostCommonNeed,
    most_common_industry: mostCommonIndustry,
    immediate_action: hot.map(h => ({ name: h.Name, business: h.Business, score: h['Qualification Score'] })),
    breakdown: { needs, industries },
    leads: todayLeads
  }
}];

